mapper.select:
SELECT COUNT(*) FROM agent_configurations
WHERE user_id = #{userId}
AND ( name ILIKE CONCAT('%', #{search}, '%') OR host ILIKE CONCAT('%', #{search}, '%') OR protocol ILIKE CONCAT('%', #{search}, '%') )

mapper.delete:
DELETE FROM agent_configurations
WHERE agent_id = #{agentId}
AND user_id = #{userId}
